<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {animalApi,contentApi} from '../api/index.js'
import {useAuth} from '../store/auth.js'
import {displayText} from '../utils/displayText.js'
import {memberUrl} from '../utils/memberApp.js'
import AuthImage from '../components/AuthImage.vue'
import BrandLockup from '../components/BrandLockup.vue'
import {demoAnimalProfiles,demoNotice,familyLetters,rescueStories,serviceScenes,trustPractices} from '../content/publicContent.js'

const route=useRoute(),auth=useAuth(),workbench=computed(()=>['ADMIN','RESCUER'].includes(auth.state.user?.roleCode))
const mode=computed(()=>route.meta.publicMode||'home'),animals=ref([]),notices=ref([]),detail=ref(null),health=ref([]),loading=ref(false),error=ref(''),species=ref(''),page=ref(1),total=ref(0),homeAnimalTotal=ref(0),homeNoticeTotal=ref(0)
const journeySteps=[{title:'发现',description:'提交现场线索'},{title:'审核',description:'核实信息风险'},{title:'救助',description:'专业人员接力'},{title:'建档',description:'持续健康照护'},{title:'领养',description:'匹配负责家庭'},{title:'回访',description:'守护长久陪伴'}]
const companionCards=[
 {to:'/guide',eyebrow:'ADOPTION GUIDE',title:'准备迎接新伙伴',description:'从居住环境到长期照护，先了解领养前需要准备的事。',action:'阅读领养指南',image:'/assets/pudding-cat-card-v2.webp'},
 {to:'/guide#rescue',eyebrow:'RESCUE TOGETHER',title:'让善意变成行动',description:'正确记录现场并提供线索，与专业救助人员一起帮助它们。',action:'了解救助流程',image:'/assets/ahei-black-dog-card-v2.webp'},
 {to:'/news',eyebrow:'PETLINK STORIES',title:'看见每一段新生活',description:'关注平台通知与近期动态，找到适合自己的参与方式。',action:'查看平台公告',image:'/assets/coffee-kitten-card-v2.webp'}
]
let sequence=0
const age=m=>m==null?'年龄待确认':m<12?`${m}个月`:`${Math.floor(m/12)}岁`
const date=d=>d?new Date(d).toLocaleDateString('zh-CN'):''
const pageCount=computed(()=>Math.max(1,Math.ceil(total.value/12)))
function goPage(next){if(next<1||next>pageCount.value||next===page.value)return;page.value=next;load();window.scrollTo({top:0,behavior:'smooth'})}
async function load(){const id=++sequence;loading.value=true;error.value='';detail.value=null;try{
  const kind=mode.value
  if(kind==='home'){const [a,n]=await Promise.all([animalApi.publicList({page:1,size:3}),contentApi.announcements({page:1,size:3})]);if(id!==sequence)return;animals.value=a.records;notices.value=n.records;homeAnimalTotal.value=a.total;homeNoticeTotal.value=n.total}
  else if(kind==='adopt'){const a=await animalApi.publicList({page:page.value,size:12,...(species.value?{species:species.value}:{})});if(id!==sequence)return;animals.value=a.records;total.value=a.total}
  else if(kind==='news'){const n=await contentApi.announcements({page:page.value,size:12});if(id!==sequence)return;notices.value=n.records;total.value=n.total}
  else if(kind==='animal'){const [a,h]=await Promise.all([animalApi.detail(route.params.id),animalApi.health(route.params.id)]);if(id!==sequence)return;if(a.status!=='AVAILABLE')throw {userMessage:'该动物暂未开放领养，请返回列表查看其他伙伴'};detail.value=a;health.value=h}
  else if(kind==='notice'){const n=await contentApi.announcement(route.params.id);if(id!==sequence)return;detail.value=n}
}catch(e){if(id===sequence)error.value=e?.userMessage||'内容加载失败，请重试'}finally{if(id===sequence)loading.value=false}}
watch(()=>route.fullPath,()=>{page.value=1;load()},{immediate:true})
</script>

